function validate([num]) {
  if (typeof num !== 'string' || num.length < 1 || num.length > 3500) return 'num needs 1 to 3500 digits.';
  if (!/^[0-9]+$/.test(num)) return 'num may contain only the digits 0 to 9.';
  return null;
}

