function numberOfCombinations(num) {
  const MOD = 1000000007;
  const n = num.length;
  const lcp = Array.from({ length: n + 1 }, () => new Uint16Array(n + 1));
  for (let a = n - 1; a >= 0; a--) {
    for (let b = n - 1; b > a; b--) {
      if (num[a] === num[b]) {
        lcp[a][b] = lcp[a + 1][b + 1] + 1;
      }
    }
  }

  const sums = Array.from({ length: n + 1 }, () => new Int32Array(n + 1));
  for (let end = 1; end <= n; end++) {
    for (let len = 1; len <= end; len++) {
      const start = end - len;
      let ways = 0;
      if (num[start] !== '0') {
        if (start === 0) {
          ways = 1;
        } else {
          ways = sums[start][Math.min(len - 1, start)];
          const prev = start - len;
          if (prev >= 0) {
            const common = lcp[prev][start];
            if (common >= len || num[prev + common] < num[start + common]) {
              ways = (ways + sums[start][len] - sums[start][len - 1] + MOD) % MOD;
            }
          }
        }
      }
      sums[end][len] = (sums[end][len - 1] + ways) % MOD;
    }
  }
  return sums[n][n];
}

