function numberOfCombinations(num) {
  const MOD = 1000000007;
  const n = num.length;
  // Without leading zeros, a longer number is bigger; equal lengths compare as strings.
  const atMost = (x, y) => x.length !== y.length ? x.length < y.length : x <= y;
  // count[i][j]: lists that spell num[0..j) and end with the number num[i..j).
  const count = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(0));
  for (let j = 1; j <= n; j++) {
    for (let i = 0; i < j; i++) {
      if (num[i] === '0') continue;
      if (i === 0) { count[i][j] = 1; continue; }
      const last = num.slice(i, j);
      let total = 0;
      for (let k = 0; k < i; k++) {
        if (count[k][i] && atMost(num.slice(k, i), last)) total = (total + count[k][i]) % MOD;
      }
      count[i][j] = total;
    }
  }
  let answer = 0;
  for (let i = 0; i < n; i++) answer = (answer + count[i][n]) % MOD;
  return answer;
}

