function generate(rand, size) {
  const pick = (alphabet) => alphabet[Math.floor(rand() * alphabet.length)];
  const shape = Math.floor(rand() * 4);
  const alphabet = shape === 0 ? '0123456789' : shape === 1 ? '01' : shape === 2 ? '1' : '1112';
  const n = size === 'large' ? 700 + Math.floor(rand() * 201) : 1 + Math.floor(rand() * 12);
  let num = '';
  for (let i = 0; i < n; i++) num += pick(alphabet);
  if (rand() < 0.85 && num[0] === '0') num = '1' + num.slice(1);
  return [num];
}
